CREATE TABLE "c_Clinician" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Clinician_npi" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Clinician')));
CREATE TABLE "c_Diagnosis" ("id" BIGINT NOT NULL, "a_Diagnosis_code" TEXT NOT NULL, "a_Diagnosis_description" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Encounter" ("id" BIGINT NOT NULL, "a_Encounter_encounter_date" TIMESTAMP NOT NULL, "r_ClinicianEncounters_source_id" BIGINT, "r_ClinicianEncounters_source_dtype" TEXT, "r_PatientEncounters_source_id" BIGINT, "r_PatientEncounters_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_ClinicianEncounters_source_dtype" IS NULL OR "r_ClinicianEncounters_source_dtype" IN ('Clinician')), CHECK ((TRUE) OR "r_ClinicianEncounters_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ClinicianEncounters_source_id" IS NOT NULL), CHECK ("r_PatientEncounters_source_dtype" IS NULL OR "r_PatientEncounters_source_dtype" IN ('Patient')), CHECK ((TRUE) OR "r_PatientEncounters_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_PatientEncounters_source_id" IS NOT NULL));
CREATE TABLE "c_Medication" ("id" BIGINT NOT NULL, "a_Medication_name" TEXT NOT NULL, "a_Medication_dose" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Patient" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Patient_mrn" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Patient')));
CREATE TABLE "c_Person" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Person_full_name" TEXT NOT NULL, "a_Person_dob" DATE NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Clinician','Patient','Person')));
CREATE TABLE "l_EncounterDiagnoses" ("r_EncounterDiagnoses_source_id" BIGINT NOT NULL, "r_EncounterDiagnoses_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_EncounterDiagnoses_source_id", "r_EncounterDiagnoses_target_id"));
CREATE TABLE "l_EncounterMedications" ("r_EncounterMedications_source_id" BIGINT NOT NULL, "r_EncounterMedications_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_EncounterMedications_source_id", "r_EncounterMedications_target_id"));
ALTER TABLE "c_Clinician" ADD CONSTRAINT "fk_c_Clinician_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Encounter" ADD CONSTRAINT "fk_c_Encounter_0" FOREIGN KEY ("r_ClinicianEncounters_source_id", "r_ClinicianEncounters_source_dtype") REFERENCES "c_Clinician" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Encounter" ADD CONSTRAINT "fk_c_Encounter_1" FOREIGN KEY ("r_PatientEncounters_source_id", "r_PatientEncounters_source_dtype") REFERENCES "c_Patient" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Patient" ADD CONSTRAINT "fk_c_Patient_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterDiagnoses" ADD CONSTRAINT "fk_l_EncounterDiagnoses_0" FOREIGN KEY ("r_EncounterDiagnoses_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterDiagnoses" ADD CONSTRAINT "fk_l_EncounterDiagnoses_1" FOREIGN KEY ("r_EncounterDiagnoses_target_id") REFERENCES "c_Diagnosis" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterMedications" ADD CONSTRAINT "fk_l_EncounterMedications_0" FOREIGN KEY ("r_EncounterMedications_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_EncounterMedications" ADD CONSTRAINT "fk_l_EncounterMedications_1" FOREIGN KEY ("r_EncounterMedications_target_id") REFERENCES "c_Medication" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;